(1400, 'franchise', '/ˈfræntʃaɪz/', 'noun / verb', '{"zh-TW":["特許經營權；加盟"],"en":["a license to sell products under a brand name"]}', NULL, 'franchise agreement/owner', '[{"en":"He owns a fast-food franchise.","zh-TW":"他擁有一家速食加盟店。"},{"en":"The brand is looking to franchise internationally.","zh-TW":"該品牌正在尋求國際特許經營。"}]', '{"noun":"franchise/franchisee/franchisor","verb":"franchise"}', NULL, 3, 1400, NULL),
(1401, 'franchisee', '/ˌfræntʃaɪˈziː/', 'noun', '{"zh-TW":["加盟商；受許可人"],"en":["a person or company that has purchased the right to operate a franchised business"]}', NULL, 'recruit franchisees / support franchisees', '[{"en":"Each franchisee operates under the franchisor''s brand and standards.","zh-TW":"每個加盟商在特許經營者的品牌和標準下運營。"},{"en":"The franchisor provides training and marketing support to all franchisees.","zh-TW":"特許經營者為所有加盟商提供培訓和行銷支持。"}]', '{"opposite":"franchisor"}', NULL, 4, 1401, NULL),
(1402, 'franchisor', '/ˈfræntʃaɪzər/', 'noun', '{"zh-TW":["特許經營者；授予特許權者"],"en":["a company that grants franchises to others to operate under its brand"]}', NULL, 'become a franchisor / franchisor obligations', '[{"en":"The franchisor is responsible for protecting the brand across all franchise locations.","zh-TW":"特許經營者負責保護所有加盟地點的品牌。"},{"en":"A franchisor earns royalties from franchisees based on sales revenue.","zh-TW":"特許經營者根據銷售收入從加盟商處獲取版稅。"}]', '{"opposite":"franchisee"}', NULL, 4, 1402, NULL),
(1403, 'free', '/friː/', 'adjective / verb', '{"zh-TW":["免費的；自由的"],"en":["without cost; not restricted"]}', NULL, 'free of charge / free up', '[{"en":"The seminar is free of charge.","zh-TW":"研討會免費。"},{"en":"We need to free up some budget.","zh-TW":"我們需要騰出一些預算。"}]', '{"noun":"freedom","verb":"free","adjective":"free","adverb":"freely"}', NULL, 1, 1403, NULL),
(1404, 'free-range', '/friː reɪndʒ/', 'adjective', '{"zh-TW":["放養的；自由放牧的"],"en":["allowing animals to roam freely"]}', NULL, 'free-range chicken / free-range eggs', '[{"en":"The restaurant uses free-range chicken in all dishes.","zh-TW":"餐廳在所有菜餚中使用放養雞肉。"},{"en":"Free-range eggs have a richer flavor.","zh-TW":"放養雞蛋風味更豐富。"}]', NULL, NULL, 4, 1404, NULL),
(1405, 'freemium', '/ˈfriːmiəm/', 'noun', '{"zh-TW":["免費增值模式"],"en":["a pricing model offering basic features free with paid premium upgrades"]}', NULL, 'freemium model / freemium strategy / convert freemium users', '[{"en":"The app uses a freemium model to attract users before upselling.","zh-TW":"該應用程式使用免費增值模式在向上銷售前吸引用戶。"},{"en":"Freemium services must balance free features with paid incentives.","zh-TW":"免費增值服務必須平衡免費功能與付費激勵。"}]', NULL, NULL, 3, 1405, NULL),
(1406, 'freight', '/freɪt/', 'noun', '{"zh-TW":["貨運；貨物"],"en":["goods transported in bulk by truck, train, ship, or aircraft"]}', NULL, 'air freight / sea freight / freight forwarding / freight cost', '[{"en":"Air freight was used for urgent shipments despite the higher cost.","zh-TW":"儘管成本較高，空運還是用於緊急貨物。"},{"en":"Sea freight is slower but much cheaper than air for bulky goods.","zh-TW":"海運比空運慢，但對大批量貨物便宜得多。"}]', '{"verb":"freight","adjective":"freight"}', NULL, 3, 1406, NULL),
(1407, 'frequent', '/ˈfriːkwənt/', 'adjective', '{"zh-TW":["頻繁的；經常的"],"en":["occurring often"]}', NULL, 'frequent traveler/visitor', '[{"en":"Frequent breaks improve productivity.","zh-TW":"頻繁休息可以提高生產力。"},{"en":"She is a frequent visitor to our office.","zh-TW":"她經常來我們辦公室。"}]', '{"noun":"frequency","adjective":"frequent","adverb":"frequently"}', NULL, 3, 1407, NULL),
