(1414, 'frustrated', '/frʌˈstreɪtɪd/', 'adjective', '{"zh-TW":["沮喪的；受挫的"],"en":["feeling upset because of inability to change or achieve something"]}', '{"root":{"text":"frustr","meaning":"in vain (徒勞)"},"suffix":{"text":"-ated","meaning":"state (狀態)"},"logic":"感到徒勞的狀態，即「受挫的」。"}', 'feel frustrated / frustrated with', '[{"en":"He felt frustrated with the slow progress.","zh-TW":"他對緩慢的進度感到挫折。"},{"en":"Customers are frustrated by the long wait times.","zh-TW":"顧客對漫長的等待時間感到不滿。"}]', '{"noun":"frustration","verb":"frustrate","adjective":"frustrating"}', NULL, 4, 1414, NULL),
(1415, 'fulfill', '/fʊlˈfɪl/', 'verb', '{"zh-TW":["履行；實現"],"en":["to carry out a duty; to satisfy a requirement"]}', NULL, 'fulfill obligations/requirements', '[{"en":"The company fulfilled all contractual obligations.","zh-TW":"公司履行了所有合約義務。"},{"en":"We strive to fulfill customer expectations.","zh-TW":"我們努力滿足客戶期望。"}]', '{"noun":"fulfillment","verb":"fulfill"}', NULL, 3, 1415, 686),
(1416, 'fulfillment', '/fʊlˈfɪlmənt/', 'noun', '{"zh-TW":["訂單履行；完成"],"en":["the process of completing a customer order, including picking and shipping"]}', NULL, 'order fulfillment / fulfillment center / fulfillment speed / fulfillment process', '[{"en":"Same-day fulfillment became a key competitive advantage.","zh-TW":"當日訂單履行成為關鍵競爭優勢。"},{"en":"The company opened a new fulfillment center to serve the East Coast.","zh-TW":"公司開設了新的訂單履行中心以服務東海岸。"}]', '{"verb":"fulfill","adjective":"fulfilled"}', NULL, 4, 1416, 576),
(1417, 'full', '/fʊl/', 'adjective', '{"zh-TW":["滿的；完整的"],"en":["containing as much as possible","complete"]}', NULL, 'full-time / in full', '[{"en":"She works full-time at the firm.","zh-TW":"她在公司全職工作。"},{"en":"Payment must be made in full.","zh-TW":"必須全額付款。"}]', '{"adjective":"full","adverb":"fully","verb":"fulfill","noun":"fullness"}', NULL, 1, 1417, NULL),
