(1419, 'fund', '/fʌnd/', 'noun / verb', '{"zh-TW":["基金；資助"],"en":["a sum of money for a purpose; to provide money"]}', NULL, 'raise/allocate funds', '[{"en":"The company raised funds for expansion.","zh-TW":"公司為擴張籌集了資金。"},{"en":"The project is funded by the government.","zh-TW":"該項目由政府資助。"}]', '{"noun":"fund/funding","verb":"fund"}', NULL, 1, 1419, 365),
(1420, 'fundamental', '/ˌfʌndəˈmentəl/', 'adjective', '{"zh-TW":["基本的；根本的"],"en":["forming a necessary base; essential"]}', '{"root":{"text":"fund","meaning":"bottom/foundation (基礎)"},"suffix":{"text":"-amental","meaning":"relating to (相關的)"},"logic":"與基礎相關的，即「根本的」。"}', 'fundamental change/principle; fundamental principle / fundamental change / fundamental right', '[{"en":"Trust is fundamental to any business relationship.","zh-TW":"信任是任何商業關係的根本。"},{"en":"There are fundamental differences between the two plans.","zh-TW":"兩個計畫之間有根本的差異。"},{"en":"Respect is fundamental to any relationship.","zh-TW":"尊重是任何關係的根本。"},{"en":"There has been a fundamental change in policy.","zh-TW":"政策發生了根本性的改變。"}]', '{"noun":"fundamentals","adjective":"fundamental","adverb":"fundamentally"}', NULL, 4, 1420, NULL),
(1421, 'funding', 'ˈfʌndɪŋ', 'noun', '{"zh-TW":["資金；經費","撥款"],"en":["money provided for a purpose","financial support"]}', NULL, 'secure funding/government funding', '[{"en":"We secured additional funding for the project.","zh-TW":"我們為項目獲得了額外資金。"}]', '{"verb":"fund","adjective":"funded"}', NULL, 3, 1421, NULL),
(1422, 'funnel', '/ˈfʌnəl/', 'noun', '{"zh-TW":["漏斗；行銷漏斗"],"en":["the stages a customer goes through from awareness to purchase"]}', NULL, 'sales funnel / marketing funnel / top of funnel / bottom of funnel', '[{"en":"Most website visitors drop off at the top of the funnel.","zh-TW":"大多數網站訪客在漏斗頂端就流失了。"},{"en":"The team optimized the funnel to reduce drop-off at checkout.","zh-TW":"團隊優化了漏斗以減少結帳時的流失。"}]', '{"verb":"funnel"}', NULL, 2, 1422, NULL),
