(1448, 'glad', '/ɡlæd/', 'adjective', '{"zh-TW":["高興的"],"en":["feeling pleasure and happiness"]}', NULL, 'glad to help / glad to hear', '[{"en":"I am glad to help you with this.","zh-TW":"我很樂意幫你處理這件事。"},{"en":"I am glad to hear the good news.","zh-TW":"我很高興聽到好消息。"}]', '{"adjective":"glad","adverb":"gladly"}', NULL, 1, 1448, NULL),
(1449, 'glass', '/ɡlæs/', 'noun', '{"zh-TW":["玻璃；玻璃杯"],"en":["a hard transparent material","a container for drinking"]}', NULL, 'glass ceiling / glass of water', '[{"en":"Women still face the glass ceiling.","zh-TW":"女性仍面臨玻璃天花板效應。"},{"en":"Would you like a glass of water?","zh-TW":"你要一杯水嗎？"}]', '{"noun":"glass","adjective":"glassy"}', NULL, 2, 1449, NULL);
