(1488, 'guideline', '/ˈɡaɪdlaɪn/', 'noun', '{"zh-TW":["準則；指導方針"],"en":["a general rule or piece of advice"]}', NULL, 'follow/establish guidelines', '[{"en":"Please follow the company guidelines.","zh-TW":"請遵循公司準則。"},{"en":"New guidelines were issued for remote work.","zh-TW":"發布了遠端工作的新指導方針。"}]', '{"noun":"guideline"}', NULL, 3, 1488, 129),
(1489, 'guidelines', '/ˈɡaɪdlaɪnz/', 'noun', '{"zh-TW":["指導方針；準則"],"en":["rules or instructions providing direction"]}', NULL, 'follow guidelines / company guidelines', '[{"en":"Please follow the company guidelines when completing the form.","zh-TW":"填寫表格時請遵循公司指導方針。"},{"en":"New employees receive a copy of the workplace guidelines.","zh-TW":"新員工會收到一份工作場所準則副本。"}]', NULL, NULL, 4, 1489, NULL),
(1490, 'gym', '/dʒɪm/', 'noun', '{"zh-TW":["健身房；體育館"],"en":["a place for physical exercise"]}', NULL, 'go to the gym / gym membership', '[{"en":"I go to the gym three times a week.","zh-TW":"我一週去健身房三次。"},{"en":"The gym has new equipment.","zh-TW":"健身房有新設備。"}]', NULL, NULL, 1, 1490, NULL),
(1491, 'gynecology', '/ˌɡaɪnɪˈkɒlədʒi/', 'noun', '{"zh-TW":["婦科學；婦產科"],"en":["the branch of medicine dealing with female reproductive health"]}', NULL, 'gynecology appointment / gynecology specialist', '[{"en":"Regular gynecology checkups are important for women''s health.","zh-TW":"定期婦科檢查對女性健康很重要。"},{"en":"She was referred to a gynecology specialist for further evaluation.","zh-TW":"她被轉介到婦科專科醫生做進一步評估。"}]', '{"noun":"gynecologist","adjective":"gynecological"}', NULL, 4, 1491, NULL),
(1492, 'habit', '/ˈhæbɪt/', 'noun', '{"zh-TW":["習慣"],"en":["a regular behavior that is hard to stop"]}', NULL, 'bad habit / form a habit', '[{"en":"Develop good work habits early.","zh-TW":"及早養成良好的工作習慣。"},{"en":"It takes 21 days to form a habit.","zh-TW":"養成一個習慣需要21天。"}]', '{"noun":"habit","adjective":"habitual","adverb":"habitually"}', NULL, 2, 1492, NULL),
(1493, 'habitat', '/ˈhæbɪtæt/', 'noun', '{"zh-TW":["棲息地；居住環境"],"en":["the natural home of an animal or plant"]}', NULL, 'natural habitat / wildlife habitat', '[{"en":"Deforestation destroys the habitat of many species.","zh-TW":"砍伐森林破壞了許多物種的棲息地。"},{"en":"The wetlands provide habitat for migratory birds.","zh-TW":"濕地為候鳥提供了棲息地。"}]', '{"noun":"habitat, habitation","verb":"inhabit"}', NULL, 3, 1493, NULL),
(1494, 'hack', '/hæk/', 'verb', '{"zh-TW":["駭入；破解"],"en":["to gain unauthorized access to a computer"]}', NULL, 'hack into / life hack', '[{"en":"Someone hacked into the system.","zh-TW":"有人駭入了系統。"},{"en":"Here''s a useful life hack.","zh-TW":"這裡有一個實用的生活小技巧。"}]', '{"noun":"hacker","noun2":"hacking"}', NULL, 1, 1494, NULL),
(1495, 'hail', '/heɪl/', 'noun', '{"zh-TW":["冰雹"],"en":["pellets of frozen rain falling from clouds"]}', '{"root":{"text":"hail","meaning":"hailstone (冰雹)"},"logic":"指從雲中落下的冰粒。"}', 'hailstorm / hail damage', '[{"en":"The hail damaged several cars in the parking lot.","zh-TW":"冰雹損壞了停車場的幾輛車。"},{"en":"A sudden hailstorm caught everyone off guard.","zh-TW":"突如其來的冰雹讓所有人措手不及。"}]', '{"noun":"hailstorm"}', NULL, 1, 1495, NULL),
(1496, 'hair', '/hɛr/', 'noun', '{"zh-TW":["頭髮；毛髮"],"en":["the thin threads growing on the head"]}', NULL, 'hairstyle / hair salon', '[{"en":"She got a new hairstyle for the event.","zh-TW":"她為活動換了新髮型。"},{"en":"There is a hair salon downstairs.","zh-TW":"樓下有一間美髮沙龍。"}]', '{"noun":"hair","adjective":"hairy","noun2":"hairstyle"}', NULL, 1, 1496, NULL),
(1497, 'halal', '/həˈlɑːl/', 'adjective', '{"zh-TW":["清真的；合乎伊斯蘭教規的"],"en":["permissible according to Islamic law"]}', NULL, 'halal food / halal certified', '[{"en":"The restaurant serves halal food for Muslim guests.","zh-TW":"餐廳為穆斯林賓客提供清真食物。"},{"en":"Please indicate if you need a halal meal on the booking form.","zh-TW":"預訂表格上請說明是否需要清真餐食。"}]', NULL, NULL, 2, 1497, NULL),
