(1667, 'inefficiency', '/ˌɪnɪˈfɪʃənsi/', 'noun', '{"zh-TW":["低效率；低效"],"en":["failure to make best use of time, money, or resources"]}', NULL, 'address inefficiencies / operational inefficiency', '[{"en":"The audit identified several inefficiencies in the procurement process.","zh-TW":"審計識別了採購流程中的幾個低效問題。"},{"en":"Inefficiency in logistics increased delivery costs significantly.","zh-TW":"物流低效顯著增加了配送成本。"}]', '{"adjective":"inefficient","adverb":"inefficiently"}', NULL, 4, 1667, NULL),
(1668, 'inevitable', '/ɪnˈevɪtəbl/', 'adjective', '{"zh-TW":["不可避免的"],"en":["certain to happen; unavoidable"]}', '{"prefix":{"text":"in-","meaning":"not (不)"},"root":{"text":"evit","meaning":"avoid (避免)"},"suffix":{"text":"-able","meaning":"able to (能夠)"},"logic":"不能避免的。"}', 'inevitable result / inevitable change; inevitable consequence/result/outcome', '[{"en":"Change is inevitable in any organization.","zh-TW":"在任何組織中，變革都是不可避免的。"},{"en":"Delays were inevitable given the weather.","zh-TW":"考慮到天氣，延遲是不可避免的。"},{"en":"Change is inevitable in any organization.","zh-TW":"變革在任何組織中都是不可避免的。"},{"en":"It was inevitable that prices would rise.","zh-TW":"價格上漲是不可避免的。"}]', '{"adverb":"inevitably","noun":"inevitability","adjective":"inevitable"}', NULL, 4, 1668, NULL),
(1669, 'infer', '/ɪnˈfɜːr/', 'verb', '{"zh-TW":["推斷；推論"],"en":["to conclude from evidence and reasoning"]}', NULL, 'infer from / can be inferred', '[{"en":"We can infer from the data that sales are declining.","zh-TW":"我們可以從數據推斷出銷售額正在下降。"},{"en":"What can be inferred from this chart?","zh-TW":"從這張圖表中可以推斷出什麼？"}]', '{"noun":"inference","verb":"infer"}', NULL, 2, 1669, NULL),
(1670, 'inferior', '/ɪnˈfɪriər/', 'adjective', '{"zh-TW":["較差的；次等的"],"en":["lower in quality, status, or rank"]}', NULL, 'inferior quality/product / feel inferior', '[{"en":"The cheaper product is inferior in quality.","zh-TW":"較便宜的產品品質較差。"},{"en":"Customers complained about inferior materials.","zh-TW":"客戶抱怨材料品質低劣。"}]', '{"noun":"inferiority","adjective":"inferior"}', NULL, 3, 1670, NULL),
(1671, 'inflation', '/ɪnˈfleɪʃn/', 'noun', '{"zh-TW":["通貨膨脹"],"en":["a general increase in prices over time"]}', NULL, 'inflation rate / fight/curb inflation / rising inflation', '[{"en":"The inflation rate reached 8% this year.","zh-TW":"今年通貨膨脹率達到8%。"},{"en":"The central bank raised interest rates to combat inflation.","zh-TW":"央行提高利率以對抗通脹。"}]', '{"noun":"inflation","verb":"inflate","adjective":"inflationary"}', NULL, 3, 1671, NULL),
(1672, 'inflation-adjusted', '/ɪnˈfleɪʃən əˈdʒʌstɪd/', 'adjective', '{"zh-TW":["經通膨調整的"],"en":["taking inflation into account to give the real value"]}', NULL, 'inflation-adjusted returns / inflation-adjusted income', '[{"en":"Inflation-adjusted wages showed a decline in real purchasing power.","zh-TW":"經通膨調整的薪資顯示實際購買力下降了。"},{"en":"Investors should evaluate inflation-adjusted returns to assess true gains.","zh-TW":"投資者應評估經通膨調整的回報以評估真實收益。"}]', NULL, NULL, 5, 1672, NULL),
(1673, 'inflow', '/ˈɪnfloʊ/', 'noun', '{"zh-TW":["流入；流入量"],"en":["the movement of money or goods into a system or account"]}', NULL, 'cash inflow / capital inflow / increase inflows', '[{"en":"Strong cash inflows allowed the company to pay down debt quickly.","zh-TW":"強勁的現金流入使公司能夠快速還清債務。"},{"en":"Foreign capital inflows boosted the local currency.","zh-TW":"外國資本流入提振了本幣。"}]', '{"opposite":"outflow"}', NULL, 2, 1673, NULL),
(1674, 'influence', '/ˈɪnfluəns/', 'noun', '{"zh-TW":["影響","影響；影響力"],"en":["the capacity to have an effect on someone or something","the power to affect someone or something"]}', '{"prefix":{"text":"in-","meaning":"in (進入)"},"root":{"text":"flu","meaning":"flow (流)"},"suffix":{"text":"-ence","meaning":"state (狀態)"},"logic":"流入其中產生作用，即「影響」。"}', 'have influence / under the influence of / positive influence; have influence on / under the influence of', '[{"en":"Social media has a huge influence on young people.","zh-TW":"社群媒體對年輕人有巨大的影響。"},{"en":"She used her influence to get the job.","zh-TW":"她利用自己的影響力得到了這份工作。"},{"en":"Social media has a huge influence on consumer behavior.","zh-TW":"社群媒體對消費者行為有巨大影響。"},{"en":"His research influenced the field significantly.","zh-TW":"他的研究對該領域產生了重大影響。"}]', '{"verb":"influence","adjective":"influential","noun":"influence"}', NULL, 3, 1674, NULL),
(1675, 'influencer', '/ˈɪnfluənsər/', 'noun', '{"zh-TW":["網路紅人；意見領袖"],"en":["a person who influences others through social media"]}', NULL, 'social media influencer / partner with an influencer', '[{"en":"The company partnered with influencers to promote the product.","zh-TW":"公司與網路紅人合作推廣產品。"},{"en":"Influencer marketing has become a major advertising strategy.","zh-TW":"網紅行銷已成為主要的廣告策略。"}]', '{"verb":"influence","adjective":"influential"}', NULL, 4, 1675, NULL),
(1676, 'inform', '/ɪnˈfɔːrm/', 'verb', '{"zh-TW":["通知；告知"],"en":["to give someone facts or information"]}', NULL, 'inform someone of/about / keep informed', '[{"en":"Please inform us of any changes to your schedule.","zh-TW":"如果您的行程有變，請通知我們。"},{"en":"We will keep you informed of the progress.","zh-TW":"我們會隨時向您通報進展。"}]', '{"noun":"information","verb":"inform","adjective":"informative, informed"}', NULL, 2, 1676, 138),
(1677, 'information', 'ˌɪnfərˈmeɪʃən', 'noun', '{"zh-TW":["信息；資訊","情報"],"en":["facts or knowledge","data"]}', NULL, 'provide information/background information', '[{"en":"For more information, visit our website.","zh-TW":"如需更多信息，請訪問我們的網站。"}]', '{"verb":"inform","adjective":"informative","adverb":"informatively"}', NULL, 4, 1677, NULL),
(1678, 'informed', 'ɪnˈfɔːrmd', 'adjective', '{"zh-TW":["知情的；了解的","消息靈通的"],"en":["having the right information","up to date"]}', NULL, 'well-informed/keep informed', '[{"en":"Please keep all stakeholders informed.","zh-TW":"請讓所有利益相關者保持知情。"}]', '{"verb":"inform","noun":"information"}', NULL, 3, 1678, NULL),
(1679, 'infrastructure', '/ˈɪnfrəstrʌktʃər/', 'noun', '{"zh-TW":["基礎設施"],"en":["the basic systems and services that a country needs to function"]}', NULL, 'transportation/IT infrastructure', '[{"en":"The government invested heavily in infrastructure.","zh-TW":"政府大力投資基礎設施。"},{"en":"Poor infrastructure hinders economic development.","zh-TW":"落後的基礎設施阻礙了經濟發展。"}]', '{"noun":"infrastructure"}', NULL, 5, 1679, 371),
(1680, 'ingredient', '/ɪnˈɡriːdiənt/', 'noun', '{"zh-TW":["食材；成分"],"en":["any of the components of a dish or recipe"]}', NULL, 'fresh ingredient / key ingredient', '[{"en":"The chef uses only locally sourced ingredients.","zh-TW":"廚師只使用當地採購的食材。"},{"en":"List all ingredients in the dish for allergy purposes.","zh-TW":"列出菜餚中的所有食材以供過敏參考。"}]', NULL, NULL, 4, 1680, NULL),
(1681, 'inherent', '/ɪnˈhɪrənt/', 'adjective', '{"zh-TW":["固有的；內在的"],"en":["existing as a natural or permanent quality"]}', NULL, 'inherent risk/problem/weakness', '[{"en":"There are inherent risks in any investment.","zh-TW":"任何投資都有固有的風險。"},{"en":"The plan has some inherent weaknesses.","zh-TW":"該計劃有一些固有的弱點。"}]', '{"adjective":"inherent","adverb":"inherently"}', NULL, 3, 1681, NULL),
(1682, 'inhibit', '/ɪnˈhɪbɪt/', 'verb', '{"zh-TW":["抑制；阻止"],"en":["to prevent or slow down a process"]}', NULL, 'inhibit growth/development/creativity', '[{"en":"Fear of failure can inhibit creativity.","zh-TW":"對失敗的恐懼會抑制創造力。"},{"en":"The drug inhibits the growth of cancer cells.","zh-TW":"這種藥物抑制癌細胞的生長。"}]', '{"noun":"inhibition, inhibitor","verb":"inhibit"}', NULL, 3, 1682, NULL),
(1683, 'initial', '/ɪˈnɪʃl/', 'adjective, noun', '{"zh-TW":["最初的；開始的","首字母"],"en":["existing at the beginning","the first letter of a name"]}', NULL, 'initial stage/phase/reaction', '[{"en":"The initial results are very promising.","zh-TW":"初步結果非常有前景。"},{"en":"Please write your initials on each page.","zh-TW":"請在每頁寫上您的姓名縮寫。"}]', '{"noun":"initial","adjective":"initial","adverb":"initially","verb":"initiate"}', NULL, 3, 1683, NULL),
(1684, 'initiate', '/ɪˈnɪʃieɪt/', 'verb', '{"zh-TW":["發起；開始"],"en":["to cause a process or action to begin"]}', NULL, 'initiate a project/discussion/process', '[{"en":"The manager initiated a review of company policies.","zh-TW":"經理發起了公司政策的審查。"},{"en":"Who initiated the negotiations?","zh-TW":"是誰發起了談判？"}]', '{"noun":"initiation, initiative, initiator","verb":"initiate","adjective":"initial"}', NULL, 3, 1684, 694),
(1685, 'initiative', '/ɪˈnɪʃətɪv/', 'noun', '{"zh-TW":["主動性；倡議","主動性；倡議；計劃"],"en":["the ability to act independently","a new plan or program","the ability to act independently; a new plan to deal with a problem"]}', '{"prefix":{"text":"in-","meaning":"into (進入)"},"root":{"text":"it","meaning":"go (走)"},"suffix":{"text":"-iative","meaning":"relating to (相關的)"},"logic":"走進去開始行動的，即「主動性」。"}', 'take the initiative / new initiative / on one''s own initiative; take the initiative / a government initiative', '[{"en":"She took the initiative to organize the event.","zh-TW":"她主動組織了這場活動。"},{"en":"The government launched a new environmental initiative.","zh-TW":"政府推出了新的環保倡議。"},{"en":"She took the initiative to organize the event.","zh-TW":"她主動組織了這次活動。"},{"en":"The company launched a new green initiative.","zh-TW":"公司發起了一項新的綠色倡議。"}]', '{"noun":"initiative, initiation","verb":"initiate"}', NULL, 4, 1685, 139),
(1686, 'injunction', '/ɪnˈdʒʌŋkʃən/', 'noun', '{"zh-TW":["禁令；法院強制令"],"en":["a court order requiring someone to do or stop doing something"]}', NULL, 'seek an injunction / court injunction', '[{"en":"The court granted an injunction preventing the company from publishing.","zh-TW":"法院頒布了禁止該公司出版的禁令。"},{"en":"A temporary injunction was issued pending the full hearing.","zh-TW":"在全面聆訊前，法院發出了臨時禁令。"}]', NULL, NULL, 4, 1686, NULL),
(1687, 'inn', '/ɪn/', 'noun', '{"zh-TW":["旅館；客棧"],"en":["a small hotel, especially in the countryside"]}', NULL, 'country inn / village inn', '[{"en":"They stayed at a cozy country inn for the weekend.","zh-TW":"他們在週末住在一家舒適的鄉村旅館。"},{"en":"The inn has only twelve rooms and offers home-cooked meals.","zh-TW":"這家客棔只有十二間客房，提供家常菜餚。"}]', NULL, NULL, 1, 1687, NULL),
(1688, 'innovation', '/ˌɪnəˈveɪʃn/', 'noun', '{"zh-TW":["創新","創新；革新"],"en":["a new method, idea, or product"]}', '{"prefix":{"text":"in-","meaning":"in (進入)"},"root":{"text":"nov","meaning":"new (新)"},"suffix":{"text":"-ation","meaning":"process (過程)"},"logic":"引入新事物的過程，即「創新」。"}', 'drive innovation / technological innovation; technological/product innovation / drive innovation', '[{"en":"Innovation is key to staying competitive.","zh-TW":"創新是保持競爭力的關鍵。"},{"en":"The company is known for its technological innovations.","zh-TW":"這家公司以技術創新聞名。"},{"en":"The company is known for its innovation in design.","zh-TW":"該公司以設計創新聞名。"}]', '{"verb":"innovate","adjective":"innovative","noun2":"innovator","noun":"innovation, innovator"}', NULL, 4, 1688, 580),
(1689, 'innovative', '/ˈɪnəveɪtɪv/', 'adjective', '{"zh-TW":["創新的"],"en":["featuring new methods or ideas"]}', NULL, 'innovative approach/solution/technology', '[{"en":"The company is known for its innovative products.","zh-TW":"該公司以其創新產品聞名。"},{"en":"We need innovative solutions to complex problems.","zh-TW":"我們需要創新的解決方案來應對複雜問題。"}]', '{"noun":"innovation, innovator","adjective":"innovative","verb":"innovate"}', NULL, 4, 1689, 885),
(1690, 'inpatient', '/ˈɪnpeɪʃənt/', 'noun', '{"zh-TW":["住院病患"],"en":["a patient who stays in a hospital for treatment"]}', NULL, 'inpatient care / inpatient treatment', '[{"en":"Inpatient care is required for serious surgeries.","zh-TW":"重大手術需要住院護理。"},{"en":"The hospital has 200 inpatient beds.","zh-TW":"這家醫院有200張住院病床。"}]', '{"adjective":"inpatient"}', NULL, 3, 1690, NULL),
(1691, 'input', '/ˈɪnpʊt/', 'noun, verb', '{"zh-TW":["投入；輸入","提供意見"],"en":["what is put in; contribution","to enter data"]}', NULL, 'provide input / input data', '[{"en":"We value your input on this project.","zh-TW":"我們重視您對這個項目的意見。"},{"en":"Please input your password to continue.","zh-TW":"請輸入您的密碼以繼續。"}]', '{"noun":"input","verb":"input"}', NULL, 2, 1691, 372),
(1692, 'inquire', '/ɪnˈkwaɪər/', 'verb', '{"zh-TW":["詢問；調查"],"en":["to ask for information"]}', NULL, 'inquire about / inquire into', '[{"en":"She called to inquire about the job opening.","zh-TW":"她打電話詢問職位空缺的事。"},{"en":"The committee will inquire into the matter.","zh-TW":"委員會將對此事進行調查。"}]', '{"noun":"inquiry","verb":"inquire"}', NULL, 3, 1692, NULL),
(1693, 'inquiry', '/ɪnˈkwaɪəri/', 'noun', '{"zh-TW":["詢問；調查"],"en":["a request for information; an official investigation"]}', NULL, 'make an inquiry / customer inquiry / public inquiry', '[{"en":"We received several inquiries about the new product.","zh-TW":"我們收到了幾份關於新產品的詢問。"},{"en":"A public inquiry was launched into the incident.","zh-TW":"對該事件展開了公開調查。"}]', '{"noun":"inquiry","verb":"inquire"}', NULL, 3, 1693, 35),
(1694, 'insert', '/ɪnˈsɜːrt/', 'verb, noun', '{"zh-TW":["插入；嵌入","插入物"],"en":["to put something inside something else","something inserted"]}', NULL, 'insert a clause/coin/key', '[{"en":"Please insert your card into the machine.","zh-TW":"請將卡片插入機器。"},{"en":"A new clause was inserted into the contract.","zh-TW":"合同中插入了一項新條款。"}]', '{"noun":"insert, insertion","verb":"insert"}', NULL, 2, 1694, NULL),
(1695, 'inside', '/ɪnˈsaɪd/', 'preposition', '{"zh-TW":["在…裡面"],"en":["in or into the interior of"]}', NULL, 'inside information / inside out', '[{"en":"He has inside knowledge of the deal.","zh-TW":"他有這筆交易的內部消息。"},{"en":"She knows the business inside out.","zh-TW":"她對這個業務瞭若指掌。"}]', '{"preposition":"inside","noun":"inside","noun2":"insider","adjective":"inside"}', NULL, 2, 1695, NULL),
(1696, 'insight', '/ˈɪnsaɪt/', 'noun', '{"zh-TW":["洞察力；見解"],"en":["a deep understanding of something"]}', NULL, 'gain/provide insight into', '[{"en":"The report provides valuable insights into consumer behavior.","zh-TW":"該報告提供了關於消費者行為的寶貴見解。"},{"en":"She has keen insight into human nature.","zh-TW":"她對人性有敏銳的洞察力。"}]', '{"noun":"insight","adjective":"insightful"}', NULL, 3, 1696, NULL),
(1697, 'insist', '/ɪnˈsɪst/', 'verb', '{"zh-TW":["堅持；堅決要求"],"en":["to demand something firmly"]}', NULL, 'insist on / insist that', '[{"en":"The client insisted on a full refund.","zh-TW":"客戶堅持要求全額退款。"},{"en":"We insist that all safety protocols be followed.","zh-TW":"我們堅持必須遵守所有安全規程。"}]', '{"noun":"insistence","verb":"insist","adjective":"insistent"}', NULL, 2, 1697, NULL),
(1698, 'insolvency', '/ɪnˈsɒlvənsi/', 'noun', '{"zh-TW":["破產；無力償債"],"en":["the state of being unable to pay debts"]}', NULL, 'risk of insolvency / declare insolvency', '[{"en":"The firm is at risk of insolvency.","zh-TW":"該公司面臨破產風險。"},{"en":"They filed for insolvency last quarter.","zh-TW":"他們上一季申請了破產。"}]', '{"noun":"insolvency","adjective":"insolvent"}', NULL, 4, 1698, NULL),
(1699, 'insolvent', '/ɪnˈsɒlvənt/', 'adjective', '{"zh-TW":["資不抵債的；破產的"],"en":["unable to pay debts when they fall due"]}', NULL, 'declared insolvent / technically insolvent', '[{"en":"The company was declared insolvent after missing three payments.","zh-TW":"公司在錯過三次還款後被宣告資不抵債。"},{"en":"Insolvent businesses can apply for protection under insolvency law.","zh-TW":"資不抵債的企業可以根據破產法申請保護。"}]', '{"noun":"insolvency"}', NULL, 3, 1699, NULL);
