(1919, 'maintain', '/meɪnˈteɪn/', 'verb', '{"zh-TW":["維持；保養","維持；保持；維修"],"en":["to keep in a particular state","to assert as true","to keep in good condition; to continue at the same level"]}', '{"root":{"text":"main","meaning":"hand (手)"},"suffix":{"text":"tain","meaning":"hold (持有)"},"logic":"用手持住不放，即「維持」。"}', 'maintain quality / maintain a relationship; maintain standards/quality/equipment', '[{"en":"It''s important to maintain a healthy lifestyle.","zh-TW":"維持健康的生活方式很重要。"},{"en":"The building is well maintained.","zh-TW":"這棟建築保養得很好。"},{"en":"It is important to maintain high standards of quality.","zh-TW":"保持高品質標準很重要。"},{"en":"The building is well maintained.","zh-TW":"這棟建築維護得很好。"}]', '{"noun":"maintenance","verb":"maintain"}', NULL, 3, 1919, 36),
(1920, 'maintenance', 'ˈmeɪntənəns', 'noun', '{"zh-TW":["維護；保養","維修"],"en":["the process of keeping something in good condition","upkeep"]}', NULL, 'regular maintenance/system maintenance', '[{"en":"Schedule regular maintenance for all machines.","zh-TW":"為所有機器安排定期維護。"}]', '{"verb":"maintain","adjective":"maintained"}', NULL, 4, 1920, 152),
