(2266, 'payroll', '/ˈpeɪroʊl/', 'noun', '{"zh-TW":["薪資名冊；薪資發放"],"en":["the total of wages paid by a company to its employees; the process of paying employees"]}', NULL, 'process payroll / payroll system / payroll taxes / payroll management', '[{"en":"The payroll is processed on the last working day of each month.","zh-TW":"薪資在每月最後一個工作日發放。"},{"en":"Payroll software automates tax calculations and direct deposits.","zh-TW":"薪資軟體自動計算稅款和直接匯款。"}]', '{"noun":"payroll administrator"}', NULL, 3, 2266, 902),
(2267, 'peace', '/piːs/', 'noun', '{"zh-TW":["和平；平靜"],"en":["freedom from disturbance","a state of calm"]}', NULL, 'peace of mind / keep the peace', '[{"en":"Insurance gives you peace of mind.","zh-TW":"保險讓你安心。"},{"en":"We want to keep the peace in the office.","zh-TW":"我們希望維持辦公室的和諧。"}]', '{"noun":"peace","adjective":"peaceful","adverb":"peacefully"}', NULL, 2, 2267, NULL),
(2268, 'peak', '/piːk/', 'noun', '{"zh-TW":["高峰；頂點"],"en":["the highest point"]}', NULL, 'peak season / reach a peak / peak performance', '[{"en":"Sales reached their peak in December.","zh-TW":"銷售在十二月達到高峰。"},{"en":"Peak hours are from 8 to 10 AM.","zh-TW":"高峰時段是早上8到10點。"}]', '{"adjective":"peak","verb":"peak"}', NULL, 1, 2268, NULL),
(2269, 'pediatrics', '/ˌpiːdiˈætrɪks/', 'noun', '{"zh-TW":["兒科；小兒科"],"en":["the branch of medicine dealing with children''s health"]}', NULL, 'pediatrics clinic / pediatrics specialist', '[{"en":"The pediatrics clinic is open on weekday mornings.","zh-TW":"兒科診所在平日早晨開放。"},{"en":"Pediatrics specialists monitor children''s development and health.","zh-TW":"兒科專科醫生監測兒童的發展和健康。"}]', '{"noun":"pediatrician","adjective":"pediatric"}', NULL, 4, 2269, NULL),
(2270, 'peg', '/peɡ/', 'verb', '{"zh-TW":["掛鈎；固定"],"en":["to fix a currency''s exchange rate to another currency or commodity"]}', NULL, 'peg the currency / currency peg', '[{"en":"The country pegged its currency to the US dollar to stabilize trade.","zh-TW":"該國將其貨幣與美元掛鈎以穩定貿易。"},{"en":"Maintaining a currency peg requires substantial foreign exchange reserves.","zh-TW":"維持貨幣掛鈎需要大量的外匯儲備。"}]', '{"noun":"peg","noun2":"currency peg"}', NULL, 1, 2270, NULL),
(2271, 'penalty', '/ˈpɛnəlti/', 'noun', '{"zh-TW":["罰款；處罰"],"en":["a punishment for breaking a rule"]}', '{"root":{"text":"pen","meaning":"punish (懲罰)"},"suffix":{"text":"-alty","meaning":"狀態"}}', 'pay a penalty / penalty clause / impose a penalty', '[{"en":"Late payment will incur a penalty.","zh-TW":"逾期付款將產生罰款。"},{"en":"The penalty for breach of contract is severe.","zh-TW":"違約的處罰很嚴重。"}]', '{"verb":"penalize","adjective":"penal"}', NULL, 3, 2271, NULL),
