(2274, 'penthouse', '/ˈpɛnthaʊs/', 'noun', '{"zh-TW":["頂樓豪華套房"],"en":["a luxury apartment or suite on the top floor"]}', NULL, 'penthouse suite / stay in a penthouse', '[{"en":"The penthouse offers stunning panoramic views.","zh-TW":"頂樓豪華套房提供令人驚嘆的全景視野。"},{"en":"The penthouse suite is the most exclusive room in the hotel.","zh-TW":"頂樓豪華套房是飯店最尊榮的房型。"}]', NULL, NULL, 3, 2274, NULL),
(2275, 'people', '/ˈpiːpəl/', 'noun', '{"zh-TW":["人們"],"en":["human beings in general"]}', NULL, 'people skills / people management', '[{"en":"Good people skills are essential for managers.","zh-TW":"良好的人際交往能力對管理者至關重要。"},{"en":"We put people first.","zh-TW":"我們以人為本。"}]', '{"noun":"people","noun2":"person","adjective":"personal"}', NULL, 2, 2275, NULL),
