(2600, 'replace', '/rɪˈpleɪs/', 'verb', '{"zh-TW":["取代；更換"],"en":["to put something new in place of"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"place","meaning":"place (放置)"}}', 'replace with / replace sb. / find a replacement', '[{"en":"We will replace the old system with a new one.","zh-TW":"我們將用新系統取代舊系統。"},{"en":"She was hired to replace the former manager.","zh-TW":"她被聘來接替前任經理。"}]', '{"noun":"replacement","adjective":"replaceable"}', NULL, 3, 2600, 200),
(2601, 'replacement', 'rɪˈpleɪsmənt', 'noun', '{"zh-TW":["更換；替代品","接替者"],"en":["someone or something substituted","the act of replacing"]}', NULL, 'find a replacement/product replacement', '[{"en":"The replacement part arrived yesterday.","zh-TW":"替換零件昨天到達了。"}]', '{"verb":"replace","adjective":"replaceable"}', NULL, 4, 2601, 615),
(2602, 'replenishment', '/rɪˈplenɪʃmənt/', 'noun', '{"zh-TW":["補貨；補充"],"en":["restoring a stock of goods to an adequate level"]}', NULL, 'schedule replenishment / automatic replenishment / stock replenishment', '[{"en":"Automated replenishment reduces the risk of stockouts.","zh-TW":"自動補貨降低了缺貨的風險。"},{"en":"The replenishment order was placed as soon as inventory hit the reorder point.","zh-TW":"庫存一觸及再訂購點就立即下達了補貨訂單。"}]', '{"verb":"replenish","adjective":"replenished"}', NULL, 5, 2602, NULL),
(2603, 'reply', 'rɪˈplaɪ', 'noun', '{"zh-TW":["回覆；答覆","回應"],"en":["an answer to a message","a response"]}', NULL, 'await a reply/in reply to', '[{"en":"We are waiting for your reply.","zh-TW":"我們正在等待您的回覆。"}]', '{"verb":"reply","adjective":"replying"}', NULL, 2, 2603, NULL),
(2604, 'report', '/rɪˈpɔːrt/', 'noun', '{"zh-TW":["報告；報告書"],"en":["a written or spoken account of a topic or event"]}', NULL, 'annual report / submit a report', '[{"en":"The team submitted the quarterly sales report.","zh-TW":"團隊提交了季度銷售報告。"},{"en":"Her report provided valuable insights for management.","zh-TW":"她的報告為管理層提供了寶貴見解。"}]', '{"verb":"report","noun":"reporter","adjective":"reported"}', NULL, 2, 2604, 201),
(2605, 'represent', '/ˌrɛprɪˈzɛnt/', 'verb', '{"zh-TW":["代表；象徵"],"en":["to act or speak for someone; to symbolize"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"present","meaning":"present (呈現)"}}', 'represent the company / represent a change', '[{"en":"She represents the company at trade shows.","zh-TW":"她代表公司參加商展。"},{"en":"This represents a significant change in policy.","zh-TW":"這代表政策的重大改變。"}]', '{"noun":"representation, representative","adjective":"representative"}', NULL, 3, 2605, NULL),
(2606, 'representation', '/ˌreprɪzenˈteɪʃən/', 'noun', '{"zh-TW":["代表；陳述"],"en":["the action of speaking on behalf of someone; also a formal statement"]}', NULL, 'legal representation / seek representation / union representation', '[{"en":"All employees have the right to union representation.","zh-TW":"所有員工都有工會代表的權利。"},{"en":"She provided written representations to the regulatory committee.","zh-TW":"她向監管委員會提交了書面陳述。"}]', '{"verb":"represent","noun":"representative"}', NULL, 5, 2606, 616),
(2607, 'representative', 'ˌrɛprɪˈzɛntətɪv', 'noun', '{"zh-TW":["代表；代理人","業務員"],"en":["a person acting on behalf of another","a sales agent"]}', NULL, 'sales representative/customer representative', '[{"en":"Our sales representative will contact you.","zh-TW":"我們的銷售代表將與您聯繫。"}]', '{"verb":"represent","adjective":"representative","adverb":"representatively"}', NULL, 5, 2607, 440),
(2608, 'repurchase', '/riːˈpɜːrtʃəs/', 'verb', '{"zh-TW":["回購；買回"],"en":["to buy back something previously sold"]}', NULL, 'repurchase shares / repurchase agreement', '[{"en":"The company announced a plan to repurchase 10% of its shares.","zh-TW":"公司宣佈計劃回購10%的股份。"},{"en":"The repurchase agreement was settled within three days.","zh-TW":"回購協議在三天內結算。"}]', '{"noun":"repurchase","adjective":"repurchased"}', NULL, 4, 2608, NULL),
(2609, 'reputation', '/ˌrɛpjuˈteɪʃən/', 'noun', '{"zh-TW":["聲譽；名譽"],"en":["the opinion people have about someone"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"put","meaning":"think (思考)"},"suffix":{"text":"-ation","meaning":"狀態"}}', 'good reputation / damage one''s reputation / build a reputation', '[{"en":"The company has an excellent reputation.","zh-TW":"公司享有卓越聲譽。"},{"en":"One mistake can damage your reputation.","zh-TW":"一個錯誤可以損害你的聲譽。"}]', '{"adjective":"reputable"}', NULL, 4, 2609, NULL),
(2610, 'request', '/rɪˈkwɛst/', 'noun', '{"zh-TW":["請求；要求"],"en":["an act of asking for something"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"quest","meaning":"seek (尋求)"}}', 'make a request / upon request / request for information', '[{"en":"We received a request for additional funding.","zh-TW":"我們收到了追加資金的請求。"},{"en":"Samples are available upon request.","zh-TW":"樣品可依要求提供。"}]', '{"verb":"request"}', NULL, 3, 2610, 202),
(2611, 'require', '/rɪˈkwaɪər/', 'verb', '{"zh-TW":["需要；要求"],"en":["to need; to demand by rule"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"quire","meaning":"seek (尋求)"}}', 'require approval / required by law / as required', '[{"en":"This position requires five years of experience.","zh-TW":"此職位需要五年經驗。"},{"en":"All visitors are required to sign in.","zh-TW":"所有訪客必須登記。"}]', '{"noun":"requirement","adjective":"required"}', NULL, 3, 2611, 55),
(2612, 'required', 'rɪˈkwaɪərd', 'adjective', '{"zh-TW":["必要的；規定的","必須的"],"en":["needed or demanded","obligatory"]}', NULL, 'required documents/required skills', '[{"en":"Please submit all required documents.","zh-TW":"請提交所有必要文件。"}]', '{"verb":"require","noun":"requirement"}', NULL, 3, 2612, NULL),
(2613, 'requirement', 'rɪˈkwaɪərmənt', 'noun', '{"zh-TW":["要求；需求","條件"],"en":["something that is needed","a necessary condition"]}', NULL, 'meet requirements/list requirements', '[{"en":"Please review the project requirements.","zh-TW":"請查看專案要求。"}]', '{"verb":"require","adjective":"required"}', NULL, 4, 2613, 441),
(2614, 'reschedule', '/ˌriːˈʃedjuːl/', 'verb', '{"zh-TW":["重新安排時間；改期"],"en":["to arrange a new time for a meeting, event, or task"]}', NULL, 'reschedule a meeting / reschedule a delivery', '[{"en":"The client asked to reschedule the meeting to the following week.","zh-TW":"客戶要求將會議改期到下週。"},{"en":"We had to reschedule the product launch due to supply delays.","zh-TW":"由於供應延遲，我們不得不重新安排產品發布時間。"}]', '{"noun":"rescheduling"}', NULL, 4, 2614, NULL),
(2615, 'research', '/rɪˈsɜːrtʃ/', 'noun', '{"zh-TW":["研究；調查"],"en":["careful study of a subject"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"search","meaning":"search (搜索)"}}', 'conduct research / research and development / market research', '[{"en":"The company invests heavily in R&D.","zh-TW":"公司大量投資研發。"},{"en":"Further research is needed.","zh-TW":"需要進一步研究。"}]', '{"verb":"research","noun":"researcher"}', NULL, 3, 2615, 203),
(2616, 'reseller', '/riːˈselər/', 'noun', '{"zh-TW":["轉售商；經銷商"],"en":["a business that purchases products to resell them, often adding value"]}', NULL, 'authorized reseller / reseller agreement / reseller program', '[{"en":"The software company works with 300 authorized resellers worldwide.","zh-TW":"軟體公司在全球與300家授權經銷商合作。"},{"en":"Resellers often provide localized support and customization.","zh-TW":"轉售商通常提供本地化支援和客製化服務。"}]', '{"verb":"resell","plural":"resellers"}', NULL, 3, 2616, NULL),
(2617, 'reservation', '/ˌrɛzərˈveɪʃən/', 'noun', '{"zh-TW":["預訂","保留意見"],"en":["a booking","doubt or uncertainty"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"serv","meaning":"keep (保持)"},"suffix":{"text":"-ation","meaning":"行為"}}', 'make a reservation / have reservations about / without reservation', '[{"en":"I''d like to make a reservation for two.","zh-TW":"我想預訂兩人座。"},{"en":"I have some reservations about the plan.","zh-TW":"我對計劃有些保留意見。"}]', '{"verb":"reserve"}', NULL, 4, 2617, 56),
(2618, 'reserve', '/rɪˈzɜːrv/', 'verb', '{"zh-TW":["預訂；保留"],"en":["to book; to keep for later use"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"serve","meaning":"keep (保持)"}}', 'reserve a room / cash reserves / reserve the right', '[{"en":"Please reserve a conference room.","zh-TW":"請預訂一間會議室。"},{"en":"We reserve the right to cancel.","zh-TW":"我們保留取消的權利。"}]', '{"noun":"reserve, reservation","adjective":"reserved"}', NULL, 3, 2618, 204),
(2619, 'reserves', '/rɪˈzɜːrvz/', 'noun', '{"zh-TW":["儲備金；準備金"],"en":["retained earnings or funds set aside for future needs or contingencies"]}', NULL, 'build up reserves / draw on reserves', '[{"en":"The company built up reserves to fund future expansion.","zh-TW":"公司積累了儲備金以資助未來的擴張。"},{"en":"Reserves provide a buffer against unexpected losses or economic downturns.","zh-TW":"儲備金在意外損失或經濟下滑時提供了緩衝。"}]', NULL, NULL, 3, 2619, NULL),
(2620, 'reside', '/rɪˈzaɪd/', 'verb', '{"zh-TW":["居住"],"en":["to live in a place"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"side","meaning":"sit (坐)"}}', 'reside in / place of residence', '[{"en":"She resides in Tokyo.","zh-TW":"她居住在東京。"},{"en":"Please provide your place of residence.","zh-TW":"請提供您的居住地。"}]', '{"noun":"residence, resident, residency","adjective":"residential"}', NULL, 2, 2620, NULL),
(2621, 'residual', '/rɪˈzɪdjuəl/', 'adjective', '{"zh-TW":["剩餘的；殘差的"],"en":["remaining after the greater part has been used or removed"]}', NULL, 'residual value / residual income / residual risk', '[{"en":"The residual value of the leased vehicle was set at 30%.","zh-TW":"租賃車輛的剩餘價值設定為30%。"},{"en":"Residual risk remains even after all mitigation measures are applied.","zh-TW":"即使採取了所有緩解措施後，殘餘風險仍然存在。"}]', '{"noun":"residual","adverb":"residually"}', NULL, 3, 2621, 925),
(2622, 'resign', '/rɪˈzaɪn/', 'verb', '{"zh-TW":["辭職"],"en":["to voluntarily leave a job"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"sign","meaning":"sign (簽署)"}}', 'resign from / letter of resignation / resign as', '[{"en":"He resigned from his position as CEO.","zh-TW":"他辭去了執行長一職。"},{"en":"Please submit your resignation in writing.","zh-TW":"請以書面形式提交辭呈。"}]', '{"noun":"resignation"}', NULL, 2, 2622, 205),
(2623, 'resignation', '/ˌrezɪɡˈneɪʃən/', 'noun', '{"zh-TW":["辭職；辭呈"],"en":["the act of voluntarily leaving a job"]}', NULL, 'submit a resignation / letter of resignation / accept a resignation', '[{"en":"She submitted her resignation after accepting a better offer.","zh-TW":"她在接受更好的工作機會後提交了辭呈。"},{"en":"The CEO''s resignation surprised the entire board.","zh-TW":"執行長的辭職讓整個董事會感到驚訝。"}]', '{"verb":"resign","adjective":"resigned"}', NULL, 4, 2623, NULL),
(2624, 'resist', '/rɪˈzɪst/', 'verb', '{"zh-TW":["抵抗；抵制"],"en":["to oppose or fight against"]}', '{"prefix":{"text":"re-","meaning":"against"},"root":{"text":"sist","meaning":"stand (站立)"}}', 'resist change / resist pressure / hard to resist', '[{"en":"Many employees resist organizational change.","zh-TW":"許多員工抵制組織變革。"},{"en":"The offer was hard to resist.","zh-TW":"這個提議很難拒絕。"}]', '{"noun":"resistance","adjective":"resistant"}', NULL, 2, 2624, NULL),
(2625, 'resolution', '/ˌrɛzəˈluːʃən/', 'noun', '{"zh-TW":["解決；決議"],"en":["the action of solving a problem or dispute"]}', NULL, 'conflict resolution / quick resolution', '[{"en":"The customer was pleased with the quick resolution of her issue.","zh-TW":"顧客對她的問題得到迅速解決感到滿意。"},{"en":"Resolution of the dispute took three weeks of negotiation.","zh-TW":"爭議的解決花了三週的談判時間。"}]', '{"verb":"resolve","adjective":"resolved"}', NULL, 4, 2625, 442),
(2626, 'resolve', '/rɪˈzɒlv/', 'verb', '{"zh-TW":["解決；決心","解決；決定"],"en":["to find a solution to a problem","to decide firmly","to find a solution; to decide firmly"]}', '{"prefix":{"text":"re-","meaning":"again (再次)"},"root":{"text":"solve","meaning":"loosen (鬆開)"},"logic":"再次鬆開（解開問題），即「解決」。"}', 'resolve a conflict / resolve an issue / resolve to; resolve an issue / resolve a dispute / resolve to do', '[{"en":"We need to resolve this issue quickly.","zh-TW":"我們需要快速解決這個問題。"},{"en":"She resolved to study harder.","zh-TW":"她決心更用功讀書。"},{"en":"We need to resolve this issue immediately.","zh-TW":"我們需要立即解決這問題。"},{"en":"The dispute was resolved through mediation.","zh-TW":"糾紛通過調解解決了。"}]', '{"noun":"resolution","adjective":"resolute"}', NULL, 3, 2626, 57),
(2627, 'resort', '/rɪˈzɔːrt/', 'noun', '{"zh-TW":["度假村","手段"],"en":["a vacation place","a course of action"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"sort","meaning":"go out (出去)"}}', 'as a last resort / resort to / tourist resort', '[{"en":"We should use legal action as a last resort.","zh-TW":"我們應將法律行動作為最後手段。"},{"en":"The conference was held at a beach resort.","zh-TW":"會議在海灘度假村舉行。"}]', '{"verb":"resort"}', NULL, 2, 2627, NULL),
(2628, 'resource', '/rɪˈsɔːrs/', 'noun', '{"zh-TW":["資源"],"en":["a supply that can be used"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"source","meaning":"rise (升起)"}}', 'human resources / natural resources / allocate resources', '[{"en":"We need to allocate resources more efficiently.","zh-TW":"我們需要更有效地分配資源。"},{"en":"Human resources handles employee matters.","zh-TW":"人力資源部處理員工事務。"}]', '{"adjective":"resourceful","verb":"resource"}', NULL, 3, 2628, 206),
(2629, 'respond', '/rɪˈspɒnd/', 'verb', '{"zh-TW":["回應；回覆"],"en":["to reply; to react"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"spond","meaning":"promise (承諾)"}}', 'respond to / respond quickly / respond in writing', '[{"en":"Please respond to the email by Friday.","zh-TW":"請於週五前回覆郵件。"},{"en":"The company responded quickly to the crisis.","zh-TW":"公司迅速回應了危機。"}]', '{"noun":"response, respondent","adjective":"responsive"}', NULL, 3, 2629, NULL),
(2630, 'response', 'rɪˈspɒns', 'noun', '{"zh-TW":["回應；答覆","響應"],"en":["an answer or reaction","something said or done in reply"]}', NULL, 'prompt response/in response to', '[{"en":"Thank you for your prompt response.","zh-TW":"感謝您的及時回應。"}]', '{"verb":"respond","adjective":"responsive","adverb":"responsively"}', NULL, 3, 2630, 58),
(2631, 'responsibility', 'rɪˌspɒnsɪˈbɪlɪti', 'noun', '{"zh-TW":["責任；職責","義務"],"en":["a duty to do something","something you are in charge of"]}', NULL, 'take responsibility/social responsibility', '[{"en":"Each team member has clear responsibilities.","zh-TW":"每個團隊成員都有明確的職責。"}]', '{"adjective":"responsible","adverb":"responsibly"}', NULL, 5, 2631, 617),
(2632, 'responsible', 'rɪˈspɒnsɪbəl', 'adjective', '{"zh-TW":["負責任的；可靠的","應負責的"],"en":["having a duty to do something","trustworthy"]}', NULL, 'responsible for/responsible person', '[{"en":"Who is responsible for this project?","zh-TW":"誰負責這個專案？"}]', '{"noun":"responsibility","adverb":"responsibly"}', NULL, 4, 2632, 59),
(2633, 'rest', '/rɛst/', 'noun', '{"zh-TW":["休息；其餘的"],"en":["a period of relaxing","the remaining part"]}', NULL, 'the rest of / get some rest', '[{"en":"I will handle the rest of the tasks.","zh-TW":"我會處理剩下的任務。"},{"en":"Get some rest before the trip.","zh-TW":"出差前好好休息。"}]', '{"noun":"rest","verb":"rest","adjective":"restful","adjective2":"restless"}', NULL, 1, 2633, NULL),
(2634, 'restoration', '/ˌrestəˈreɪʃn/', 'noun', '{"zh-TW":["修復；恢復"],"en":["the act of returning something to its original condition"]}', '{"prefix":{"text":"re-","meaning":"back (回)"},"root":{"text":"stor","meaning":"set up (建立)"},"suffix":{"text":"-ation","meaning":"process (過程)"},"logic":"重新建立的過程，即「修復」。"}', 'art restoration / building restoration', '[{"en":"The restoration of the painting took three years.","zh-TW":"這幅畫的修復花了三年。"},{"en":"The old building underwent a complete restoration.","zh-TW":"這棟老建築進行了全面修復。"}]', '{"verb":"restore"}', NULL, 4, 2634, NULL),
(2635, 'restore', '/rɪˈstɔːr/', 'verb', '{"zh-TW":["恢復；修復"],"en":["to bring back to a former condition"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"store","meaning":"build (建造)"}}', 'restore confidence / restore service / restore to', '[{"en":"We aim to restore customer confidence.","zh-TW":"我們旨在恢復客戶信心。"},{"en":"Service has been fully restored.","zh-TW":"服務已完全恢復。"}]', '{"noun":"restoration"}', NULL, 3, 2635, 926),
(2636, 'restrict', '/rɪˈstrɪkt/', 'verb', '{"zh-TW":["限制；約束"],"en":["to put a limit on"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"strict","meaning":"draw tight (拉緊)"}}', 'restrict access / restrict spending / restricted area', '[{"en":"Access is restricted to authorized personnel.","zh-TW":"僅限授權人員進入。"},{"en":"The budget restricts our spending options.","zh-TW":"預算限制了我們的開支選項。"}]', '{"noun":"restriction","adjective":"restrictive, restricted"}', NULL, 3, 2636, NULL),
(2637, 'restructure', '/ˌriːˈstrʌktʃər/', 'verb', '{"zh-TW":["重組；改組"],"en":["to organize differently"]}', NULL, 'restructure debt / corporate restructuring', '[{"en":"The company plans to restructure its divisions.","zh-TW":"公司計畫重組其部門。"},{"en":"Debt restructuring saved the business.","zh-TW":"債務重組拯救了這家企業。"}]', '{"verb":"restructure","noun":"restructuring"}', NULL, 4, 2637, 717),
(2638, 'restructuring', '/riːˈstrʌktʃərɪŋ/', 'noun', '{"zh-TW":["重組；改組"],"en":["reorganizing a company''s structure, operations, or finances"]}', NULL, 'corporate restructuring / debt restructuring', '[{"en":"The restructuring plan will eliminate 500 jobs.","zh-TW":"重組計劃將裁減500個職位。"},{"en":"Debt restructuring gave the firm a fresh start.","zh-TW":"債務重組給公司提供了重新開始的機會。"}]', '{"verb":"restructure","adjective":"restructured"}', NULL, 5, 2638, 618),
(2639, 'result', '/rɪˈzʌlt/', 'noun', '{"zh-TW":["結果"],"en":["an outcome; a consequence"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"sult","meaning":"jump (跳)"}}', 'as a result / achieve results / result in', '[{"en":"As a result of the merger, profits increased.","zh-TW":"合併的結果是利潤增加了。"},{"en":"The campaign resulted in higher sales.","zh-TW":"活動帶來了更高的銷售額。"}]', '{"verb":"result","adjective":"resulting, resultant"}', NULL, 2, 2639, 444),
(2640, 'results-oriented', 'rɪˈzʌlts ˈɔːriɛntɪd', 'adjective', '{"zh-TW":["以結果為導向的；注重成效的","目標明確的"],"en":["focused on achieving outcomes","driven by results"]}', NULL, 'results-oriented culture/results-oriented manager', '[{"en":"We foster a results-oriented culture.","zh-TW":"我們培育以結果為導向的文化。"}]', NULL, NULL, 5, 2640, NULL),
(2641, 'resume', '/rɪˈzjuːm/', 'verb', '{"zh-TW":["恢復；繼續"],"en":["to begin again after a pause"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"sume","meaning":"take (拿)"}}', 'resume work / resume operations / resume negotiations', '[{"en":"Operations will resume on Monday.","zh-TW":"營運將於週一恢復。"},{"en":"Talks are expected to resume next week.","zh-TW":"會談預計下週恢復。"}]', '{"noun":"resumption"}', NULL, 2, 2641, NULL),
(2642, 'retail', '/ˈriːteɪl/', 'noun', '{"zh-TW":["零售"],"en":["the sale of goods to the public in small quantities","the sale of goods to the public"]}', '{"prefix":{"text":"re-","meaning":"again (再次)"},"root":{"text":"tail","meaning":"cut (切割)"},"logic":"再次切割分售，即「零售」。"}', 'retail price / retail store / retail industry', '[{"en":"The retail price is higher than the wholesale price.","zh-TW":"零售價比批發價高。"},{"en":"She has years of experience in retail.","zh-TW":"她有多年零售業經驗。"},{"en":"The retail price is $49.99.","zh-TW":"零售價為49.99美元。"},{"en":"She has 10 years of retail experience.","zh-TW":"她有十年零售經驗。"}]', '{"noun":"retailer","verb":"retail"}', NULL, 2, 2642, 445),
(2643, 'retain', '/rɪˈteɪn/', 'verb', '{"zh-TW":["保留；留住","保持；留住"],"en":["to keep; to continue to have","to continue to have; to keep"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"tain","meaning":"hold (持有)"}}', 'retain customers / retain employees / retain the right; retain customers / retain knowledge / retention rate', '[{"en":"The company strives to retain top talent.","zh-TW":"公司努力留住頂尖人才。"},{"en":"We retain the right to modify terms.","zh-TW":"我們保留修改條款的權利。"},{"en":"Customer retention is a key metric.","zh-TW":"客戶留存率是關鍵指標。"},{"en":"How do we retain skilled workers?","zh-TW":"我們如何留住熟練工人？"}]', '{"noun":"retention","adjective":"retentive"}', NULL, 2, 2643, 207),
(2644, 'retention', 'rɪˈtɛnʃən', 'noun', '{"zh-TW":["留住；保留","記憶"],"en":["keeping employees or customers","the ability to retain"]}', NULL, 'employee retention/customer retention', '[{"en":"Improving retention is a top priority.","zh-TW":"提高留存率是首要任務。"}]', '{"verb":"retain","adjective":"retained"}', NULL, 3, 2644, 446),
(2645, 'retire', '/rɪˈtaɪər/', 'verb', '{"zh-TW":["退休"],"en":["to stop working due to age"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"tire","meaning":"draw (拉)"}}', 'retire from / retirement age / retire early', '[{"en":"She plans to retire at 60.","zh-TW":"她計劃60歲退休。"},{"en":"He retired from the company after 30 years.","zh-TW":"他在公司工作30年後退休。"}]', '{"noun":"retirement, retiree","adjective":"retired"}', NULL, 2, 2645, NULL),
(2646, 'retrieve', '/rɪˈtriːv/', 'verb', '{"zh-TW":["取回；檢索","取回"],"en":["to get back; to find and bring back","to get something back"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"trieve","meaning":"find (找到)"}}', 'retrieve data / retrieve information / retrieve from; retrieve data / retrieve information / information retrieval', '[{"en":"We can retrieve the deleted files.","zh-TW":"我們可以檢索已刪除的文件。"},{"en":"The system retrieves data automatically.","zh-TW":"系統自動檢索數據。"},{"en":"The system can retrieve archived records.","zh-TW":"系統可以檢索存檔記錄。"},{"en":"Click here to retrieve your password.","zh-TW":"點擊此處找回密碼。"}]', '{"noun":"retrieval"}', NULL, 3, 2646, NULL),
(2647, 'retrospective', '/ˌretrəˈspektɪv/', 'noun', '{"zh-TW":["回顧會議；回顧"],"en":["a meeting where a team reflects on past work to improve future performance"]}', NULL, 'run a retrospective / sprint retrospective / agile retrospective', '[{"en":"The retrospective highlighted that daily standups improved team sync.","zh-TW":"回顧會議強調每日站立會議改善了團隊同步。"},{"en":"Retrospectives are a core ceremony in agile development.","zh-TW":"回顧是敏捷開發的核心儀式。"}]', '{"adjective":"retrospective"}', NULL, 5, 2647, NULL),
(2648, 'return', '/rɪˈtɜːrn/', 'verb', '{"zh-TW":["返回；歸還","回報"],"en":["to come or go back","to give back","profit"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"turn","meaning":"turn (轉)"}}', 'return on investment / return a call / return policy', '[{"en":"The return on investment exceeded expectations.","zh-TW":"投資回報超出預期。"},{"en":"Please return the signed contract.","zh-TW":"請歸還已簽署的合約。"}]', '{"noun":"return"}', NULL, 2, 2648, NULL),
(2649, 'reveal', '/rɪˈviːl/', 'verb', '{"zh-TW":["揭露；顯示","揭示；透露"],"en":["to make known something previously hidden","to make known; to show"]}', '{"prefix":{"text":"re-","meaning":"back (回)"},"root":{"text":"veal","meaning":"veil/cover (遮蓋)"},"logic":"把遮蓋拉回，即「揭露」。"}', 'reveal the truth / reveal information / reveal a secret; reveal information / reveal the truth / reveal findings', '[{"en":"The investigation revealed new evidence.","zh-TW":"調查揭露了新證據。"},{"en":"She revealed her plans for the future.","zh-TW":"她透露了未來的計畫。"},{"en":"The audit revealed several discrepancies.","zh-TW":"審計揭示了幾處差異。"},{"en":"The survey revealed customer preferences.","zh-TW":"調查揭示了客戶偏好。"}]', '{"noun":"revelation","adjective":"revealing"}', NULL, 2, 2649, NULL);
