(2778, 'showcase', '/ˈʃoʊkeɪs/', 'noun, verb', '{"zh-TW":["展示；陳列","展示"],"en":["a display or exhibition","to exhibit or present"]}', NULL, 'showcase products / showcase talent / showcase innovation', '[{"en":"The event showcases the latest industry innovations.","zh-TW":"活動展示了最新的產業創新。"},{"en":"We need a platform to showcase our work.","zh-TW":"我們需要一個平台來展示我們的工作。"}]', '{"noun":"showcase","verb":"showcase"}', NULL, 3, 2778, NULL),
(2779, 'shower', '/ˈʃaʊər/', 'noun', '{"zh-TW":["陣雨；淋浴"],"en":["a brief fall of rain","a device for washing the body"]}', '{"root":{"text":"shower","meaning":"brief rain (短雨)"},"logic":"指短暫的降雨或用水沖洗。"}', 'rain shower / take a shower / scattered showers', '[{"en":"Scattered showers are expected this afternoon.","zh-TW":"今天下午預計會有零星陣雨。"},{"en":"I take a shower every morning.","zh-TW":"我每天早上淋浴。"}]', '{"adjective":"showery"}', NULL, 2, 2779, NULL),
(2780, 'shrink', '/ʃrɪŋk/', 'verb', '{"zh-TW":["縮小；萎縮"],"en":["to become smaller in size or amount"]}', NULL, 'shrink in size / shrink the budget / profit margins shrink', '[{"en":"The economy shrank by 2% last quarter.","zh-TW":"上季度經濟萎縮了2%。"},{"en":"Rising costs have shrunk profit margins.","zh-TW":"成本上升壓縮了利潤率。"}]', '{"noun":"shrinkage","verb":"shrink"}', NULL, 2, 2780, NULL),
(2781, 'shrinkage', '/ˈʃrɪŋkɪdʒ/', 'noun', '{"zh-TW":["損耗；庫存損失"],"en":["the reduction in stock due to theft, damage, or recording errors"]}', NULL, 'reduce shrinkage / shrinkage rate / inventory shrinkage', '[{"en":"Tighter security measures reduced shrinkage by 30%.","zh-TW":"更嚴格的安全措施將損耗減少了30%。"},{"en":"Annual shrinkage costs the retail industry billions of dollars.","zh-TW":"年度損耗使零售業損失了數十億元。"}]', NULL, NULL, 3, 2781, NULL),
(2782, 'shuttle', '/ˈʃʌtəl/', 'noun', '{"zh-TW":["接駁車；班車"],"en":["a vehicle regularly traveling between two places"]}', NULL, 'airport shuttle / hotel shuttle', '[{"en":"Take the free shuttle from the airport to the hotel.","zh-TW":"搭乘機場到飯店的免費接駁車。"},{"en":"The shuttle runs every fifteen minutes.","zh-TW":"接駁車每十五分鐘一班。"}]', '{"verb":"shuttle"}', NULL, 3, 2782, NULL),
(2783, 'side', '/saɪd/', 'noun', '{"zh-TW":["邊；方面"],"en":["a position to the left or right","an aspect"]}', NULL, 'on the side / side effect', '[{"en":"She runs a business on the side.","zh-TW":"她兼營一項副業。"},{"en":"Consider both sides of the argument.","zh-TW":"考慮論點的兩面。"}]', '{"noun":"side","adjective":"side","noun2":"sidebar"}', NULL, 1, 2783, NULL),
(2784, 'sightseeing', '/ˈsaɪtsiːɪŋ/', 'noun', '{"zh-TW":["觀光；遊覽"],"en":["the activity of visiting famous places"]}', NULL, 'go sightseeing / sightseeing tour', '[{"en":"We spent the afternoon sightseeing in the old city.","zh-TW":"我們下午在舊城區觀光。"},{"en":"The sightseeing bus offers a hop-on hop-off service.","zh-TW":"觀光巴士提供隨上隨下服務。"}]', '{"verb":"sightsee","noun":"sightseer"}', NULL, 4, 2784, NULL),
(2785, 'sign', '/saɪn/', 'noun, verb', '{"zh-TW":["標誌；跡象","簽署；簽名"],"en":["an indication or symbol","to write one''s name on a document"]}', NULL, 'sign a contract / sign of progress / warning sign', '[{"en":"Both parties signed the agreement today.","zh-TW":"雙方今天簽署了協議。"},{"en":"There are signs of economic recovery.","zh-TW":"有經濟復甦的跡象。"}]', '{"noun":"sign, signature, signal","verb":"sign, signal"}', NULL, 1, 2785, NULL),
(2786, 'sign-off', '/ˈsaɪn ɒf/', 'noun', '{"zh-TW":["批准；最終確認"],"en":["formal approval or authorization of work or a decision"]}', NULL, 'get sign-off / require sign-off / sign-off process / management sign-off', '[{"en":"Designs require sign-off from the marketing director before printing.","zh-TW":"設計在印刷前需要行銷總監的批准。"},{"en":"The final deliverable received sign-off from all stakeholders.","zh-TW":"最終可交付成果獲得了所有利益相關者的確認。"}]', '{"verb":"sign off"}', NULL, 3, 2786, NULL),
(2787, 'signatory', '/ˈsɪɡnətɔːri/', 'noun', '{"zh-TW":["簽署人；簽字方"],"en":["a party that has signed an agreement or contract"]}', NULL, 'signatory to an agreement / co-signatory / all signatories', '[{"en":"All signatories must be present for the contract to be binding.","zh-TW":"所有簽署人必須在場，合約才具有約束力。"},{"en":"The company is a signatory to the international environmental accord.","zh-TW":"公司是國際環境協議的簽署方。"}]', '{"plural":"signatories"}', NULL, 3, 2787, NULL),
(2788, 'signature', 'ˈsɪɡnɪtʃər', 'noun', '{"zh-TW":["簽名；署名","特徵"],"en":["a person''s name written by hand","a distinctive mark"]}', NULL, 'digital signature/require a signature', '[{"en":"Please provide your signature to confirm.","zh-TW":"請提供您的簽名以確認。"}]', '{"verb":"sign","adjective":"signed"}', NULL, 3, 2788, NULL),
(2789, 'significant', '/sɪɡˈnɪfɪkənt/', 'adjective', '{"zh-TW":["重要的；顯著的","重大的；顯著的"],"en":["large enough to be noticed or have an effect","large or important enough to have an effect"]}', '{"root":{"text":"sign","meaning":"mark (標記)"},"suffix":{"text":"-ificant","meaning":"making (造成)"},"logic":"造成明顯標記的，即「顯著的」。"}', 'significant improvement / significant difference / statistically significant; significant improvement / significant impact / statistically significant', '[{"en":"There has been a significant improvement in sales.","zh-TW":"銷售額有了顯著改善。"},{"en":"This is a significant achievement.","zh-TW":"這是一項重大成就。"},{"en":"There has been a significant increase in sales.","zh-TW":"銷售額有了顯著的增長。"},{"en":"The new policy made a significant impact.","zh-TW":"新政策產生了重大影響。"}]', '{"noun":"significance","adverb":"significantly","adjective":"significant, insignificant"}', NULL, 4, 2789, 216),
(2790, 'similar', '/ˈsɪmɪlər/', 'adjective', '{"zh-TW":["相似的；類似的"],"en":["resembling without being identical"]}', NULL, 'similar to / similar results / in a similar way', '[{"en":"Our products are similar to theirs in quality.","zh-TW":"我們的產品在品質上與他們的相似。"},{"en":"We faced a similar problem last year.","zh-TW":"去年我們面臨了類似的問題。"}]', '{"noun":"similarity","adjective":"similar","adverb":"similarly"}', NULL, 3, 2790, NULL),
(2791, 'simple', '/ˈsɪmpəl/', 'adjective', '{"zh-TW":["簡單的"],"en":["easy to understand or do"]}', NULL, 'keep it simple / simple solution', '[{"en":"Keep the design simple and clean.","zh-TW":"保持設計簡潔。"},{"en":"There is a simple solution to this.","zh-TW":"這有一個簡單的解決辦法。"}]', '{"adjective":"simple","adverb":"simply","verb":"simplify","noun":"simplicity"}', NULL, 2, 2791, NULL),
(2792, 'simplify', '/ˈsɪmplɪfaɪ/', 'verb', '{"zh-TW":["簡化"],"en":["to make something easier to understand or do"]}', '{"suffix":{"text":"-ify","meaning":"使..."}}', 'simplify the process / simplify procedures', '[{"en":"We simplified the application process.","zh-TW":"我們簡化了申請流程。"},{"en":"The new software simplifies data management.","zh-TW":"新軟體簡化了資料管理。"}]', '{"noun":"simplification, simplicity","verb":"simplify","adjective":"simple"}', NULL, 3, 2792, 720),
(2793, 'simulate', '/ˈsɪmjuleɪt/', 'verb', '{"zh-TW":["模擬；模仿"],"en":["to imitate or reproduce conditions"]}', NULL, 'simulate conditions / simulate a scenario', '[{"en":"The software can simulate real-world conditions.","zh-TW":"這個軟體可以模擬真實世界的條件。"},{"en":"They simulated an emergency drill.","zh-TW":"他們模擬了一次緊急演練。"}]', '{"noun":"simulation, simulator","verb":"simulate","adjective":"simulated"}', NULL, 3, 2793, NULL),
(2794, 'simultaneous', '/ˌsaɪmlˈteɪniəs/', 'adjective', '{"zh-TW":["同時的；同步的"],"en":["occurring at the same time"]}', NULL, 'simultaneous translation / simultaneous events', '[{"en":"The event will have simultaneous translation.","zh-TW":"活動將提供同步翻譯。"},{"en":"Both teams made simultaneous announcements.","zh-TW":"兩個團隊同時發布了公告。"}]', '{"noun":"simultaneity","adjective":"simultaneous","adverb":"simultaneously"}', NULL, 4, 2794, NULL),
(2795, 'sincere', '/sɪnˈsɪr/', 'adjective', '{"zh-TW":["真誠的"],"en":["free from pretense; genuine"]}', '{"root":{"text":"sincer","meaning":"pure/clean (純淨)"},"logic":"源自拉丁語 sincerus（純淨的），指不虛偽的。"}', 'sincere apology / sincere gratitude', '[{"en":"She offered a sincere apology.","zh-TW":"她表達了真誠的歉意。"},{"en":"He is sincere in his desire to help.","zh-TW":"他真心想幫忙。"}]', '{"noun":"sincerity","adverb":"sincerely"}', NULL, 3, 2795, NULL),
(2796, 'sit', '/sɪt/', 'verb', '{"zh-TW":["坐"],"en":["to rest in a seated position"]}', NULL, 'sit down / sit in on', '[{"en":"Please sit down and make yourself comfortable.","zh-TW":"請坐下來放輕鬆。"},{"en":"May I sit in on the meeting?","zh-TW":"我可以旁聽這個會議嗎？"}]', '{"verb":"sit","noun":"seat","noun2":"sitting"}', NULL, 1, 2796, NULL),
(2797, 'site', '/saɪt/', 'noun', '{"zh-TW":["地點；場所","網站"],"en":["a place where something is located","a website"]}', NULL, 'construction site / on-site / website', '[{"en":"The construction site will be inspected tomorrow.","zh-TW":"施工現場明天將接受檢查。"},{"en":"Please visit our website for more information.","zh-TW":"請訪問我們的網站了解更多資訊。"}]', '{"noun":"site"}', NULL, 1, 2797, NULL),
(2798, 'situate', '/ˈsɪtʃueɪt/', 'verb', '{"zh-TW":["使位於；使處於"],"en":["to put in a certain position or context"]}', NULL, 'situated in / favorably situated', '[{"en":"The office is situated in the city center.","zh-TW":"辦公室位於市中心。"},{"en":"The company is well situated for growth.","zh-TW":"公司處於有利的成長位置。"}]', '{"noun":"situation","verb":"situate","adjective":"situated"}', NULL, 3, 2798, NULL),
(2799, 'size', '/saɪz/', 'noun', '{"zh-TW":["大小；規模","尺寸；大小"],"en":["how big or small something is","how large or small something is"]}', '{"root":{"text":"size","meaning":"measure (量度)"},"logic":"源自古法語 sise，指物品的量度。"}', 'market size / full-size; what size / size chart / one size fits all', '[{"en":"The market size is estimated at $5 billion.","zh-TW":"市場規模估計為50億美元。"},{"en":"What size do you need?","zh-TW":"你需要什麼尺寸？"},{"en":"What size do you wear?","zh-TW":"你穿什麼尺寸？"},{"en":"This shirt comes in three sizes.","zh-TW":"這件襯衫有三種尺寸。"}]', '{"noun":"size","adjective":"sizable","verb":"size","adjective2":"oversized"}', NULL, 1, 2799, NULL);
