(3079, 'transfer', '/ˈtrænsfɜːr/', 'noun, verb', '{"zh-TW":["轉移；調動","轉移；轉讓"],"en":["the act of moving something","to move from one place to another"]}', NULL, 'transfer funds / knowledge transfer / transfer to', '[{"en":"She transferred to the London office.","zh-TW":"她調到了倫敦辦公室。"},{"en":"Please transfer the funds to this account.","zh-TW":"請將資金轉入此帳戶。"}]', '{"noun":"transfer, transference","verb":"transfer","adjective":"transferable"}', NULL, 3, 3079, 66),
(3080, 'transform', '/trænsˈfɔːrm/', 'verb', '{"zh-TW":["轉變；改造"],"en":["to change completely in form or character"]}', '{"prefix":{"text":"trans-","meaning":"across (跨越)"},"root":{"text":"form","meaning":"shape (形狀)"},"logic":"跨越到另一種形態，即「轉變」。"}', 'transform into / digital transformation; digital transformation / transform the business / transform into', '[{"en":"Technology has transformed the way we work.","zh-TW":"科技改變了我們的工作方式。"},{"en":"The city has been transformed in recent years.","zh-TW":"這座城市近年來已經蛻變。"},{"en":"The company is undergoing a digital transformation.","zh-TW":"公司正在進行數位轉型。"}]', '{"noun":"transformation","adjective":"transformative","verb":"transform"}', NULL, 3, 3080, NULL),
(3081, 'transit', '/ˈtrænsɪt/', 'noun', '{"zh-TW":["過境；運輸"],"en":["the process of passing through a place to another destination"]}', NULL, 'in transit / transit passenger', '[{"en":"Passengers in transit do not need to collect their luggage.","zh-TW":"過境旅客不需要提取行李。"},{"en":"The transit lounge is available for connecting passengers.","zh-TW":"轉機旅客可使用過境候機室。"}]', '{"verb":"transit","adjective":"transient"}', NULL, 3, 3081, NULL),
