(3083, 'transmit', '/trænzˈmɪt/', 'verb', '{"zh-TW":["傳送；傳輸"],"en":["to send or pass on from one place to another"]}', NULL, 'transmit data / transmit information / transmit electronically', '[{"en":"The system transmits data in real time.","zh-TW":"系統即時傳輸數據。"},{"en":"Reports are transmitted electronically to headquarters.","zh-TW":"報告以電子方式傳送到總部。"}]', '{"noun":"transmission, transmitter","verb":"transmit"}', NULL, 3, 3083, NULL),
(3084, 'transparency', '/trænsˈpærənsi/', 'noun', '{"zh-TW":["透明度；透明性"],"en":["the quality of being open and honest in business operations"]}', NULL, 'financial transparency / transparency in reporting', '[{"en":"Transparency builds trust with investors and the public.","zh-TW":"透明度建立與投資者和公眾的信任。"},{"en":"The report praised the company''s financial transparency.","zh-TW":"報告稱讚了公司的財務透明度。"}]', '{"adjective":"transparent","adverb":"transparently"}', NULL, 4, 3084, 943),
