(3093, 'trend', '/trend/', 'noun', '{"zh-TW":["趨勢；動向"],"en":["a general direction of change"]}', NULL, 'market trend / upward trend / follow a trend', '[{"en":"The trend toward remote work is accelerating.","zh-TW":"遠端工作的趨勢正在加速。"},{"en":"Market trends indicate growing consumer confidence.","zh-TW":"市場趨勢顯示消費者信心增長。"}]', '{"noun":"trend","adjective":"trending, trendy"}', NULL, 2, 3093, 471),
(3094, 'trigger', '/ˈtrɪɡər/', 'noun, verb', '{"zh-TW":["觸發因素","觸發；引起"],"en":["something that causes an event","to cause something to happen"]}', NULL, 'trigger a response / trigger growth / trigger an alert', '[{"en":"The announcement triggered a sell-off in the market.","zh-TW":"該公告引發了市場拋售。"},{"en":"Rising costs triggered a review of the budget.","zh-TW":"成本上升觸發了對預算的審查。"}]', '{"noun":"trigger","verb":"trigger"}', NULL, 3, 3094, NULL),
